"""Spider enemy (your "Poison Skull" pixel art set, v1.2, outline version). All frames face left.
idle / walk / attack / hurt / death. sp_frame(anim, i) gives (surface, ax, ay): (ax, ay) is the body centre inside it."""
import base64
import zlib
import pygame

FW, FH = 120, 50
AX, AY = 82, 26                    # body centre inside a frame (1x)
BOTTOM = 48                        # lowest pixel of the creature in a frame (1x)
SCALE = 0.8
SP = {'idle': (13, ''), 'walk': (8, ''), 'attack': (16, ''), 'hurt': (6, ''), 'death': (11, '')}
_C = {}


def sp_count(anim):
  return SP[anim][0]


def sp_frame(anim, i, scale=SCALE, clamp=False):
  n, data = SP[anim]
  i = max(0, min(n - 1, int(i))) if clamp else int(i) % n
  k = (anim, i, scale)
  hit = _C.get(k)
  if hit is None:
    raw = _C.get((anim, 'raw'))
    if raw is None:
      raw = _C[(anim, 'raw')] = zlib.decompress(base64.b64decode(data))
    m = FW * FH * 4
    s = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (FW, FH), 'RGBA').copy()
    if scale != 1:
      s = pygame.transform.scale(s, (int(FW * scale), int(FH * scale)))
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    hit = _C[k] = (s, int(AX * scale), int(AY * scale))
  return hit
